import SwiftUI struct ForgotPasswordView: View { @Environment(\.dismiss) private var dismiss @StateObject private var auth = AuthService.shared @State private var email = "" @State private var code = "" @State private var newPass = "" @State private var step = 1 // 1 = enter email, 2 = enter code + new password @State private var error: String? = nil @State private var loading = false var body: some View { NavigationStack { VStack(spacing: 24) { Image(systemName: "lock.rotation") .font(.system(size: 56)) .foregroundColor(.orange) .padding(.top, 32) if step == 1 { Text("Reset Password") .font(.largeTitle.bold()) Text("Enter your email and we will send a reset code.") .foregroundColor(.secondary) .multilineTextAlignment(.center) .padding(.horizontal) TextField("Email", text: $email) .textFieldStyle(.roundedBorder) .keyboardType(.emailAddress) .autocapitalization(.none) .padding(.horizontal) Button(action: sendCode) { if loading { ProgressView().frame(maxWidth: .infinity) } else { Text("Send Reset Code").frame(maxWidth: .infinity) } } .buttonStyle(.borderedProminent) .disabled(email.isEmpty || loading) .padding(.horizontal) } else { Text("Enter Reset Code") .font(.largeTitle.bold()) Text("Check **\(email)** for your 6-digit code.") .foregroundColor(.secondary) .multilineTextAlignment(.center) .padding(.horizontal) VStack(spacing: 12) { TextField("6-digit code", text: $code) .textFieldStyle(.roundedBorder) .keyboardType(.numberPad) .multilineTextAlignment(.center) SecureField("New Password (8+ characters)", text: $newPass) .textFieldStyle(.roundedBorder) } .padding(.horizontal) Button(action: resetPassword) { if loading { ProgressView().frame(maxWidth: .infinity) } else { Text("Reset Password").frame(maxWidth: .infinity) } } .buttonStyle(.borderedProminent) .disabled(code.count < 6 || newPass.count < 8 || loading) .padding(.horizontal) } if let error = error { Text(error).font(.caption).foregroundColor(.red) } Spacer() } .navigationTitle("Forgot Password") .navigationBarTitleDisplayMode(.inline) .toolbar { ToolbarItem(placement: .cancellationAction) { Button("Cancel") { dismiss() } } } } } func sendCode() { loading = true; error = nil Task { do { try await auth.forgotPassword(email: email) step = 2 } catch { self.error = error.localizedDescription } loading = false } } func resetPassword() { loading = true; error = nil Task { do { try await auth.confirmForgotPassword(email: email, code: code, newPassword: newPass) dismiss() } catch { self.error = error.localizedDescription } loading = false } } }
